{
  "accounts": {
    "notes": "Account identity and billing configuration.",
    "writable": false,
    "selectors": [
      "account_id",
      "org"
    ],
    "fields": {
      "account_id": {
        "type": "string",
        "required": true
      },
      "org": {
        "type": "string",
        "required": true
      },
      "plan": {
        "type": "string",
        "enum": [
          "free",
          "self_serve",
          "enterprise"
        ],
        "required": true
      },
      "plan_name": {
        "type": "string",
        "required": true
      },
      "billing_channel": {
        "type": "string",
        "enum": [
          "direct",
          "aws_marketplace",
          "gcp_marketplace"
        ],
        "required": true
      },
      "status": {
        "type": "string",
        "enum": [
          "active",
          "suspended"
        ],
        "required": true
      },
      "payment_method": {
        "type": "string",
        "enum": [
          "card",
          "invoice",
          "marketplace",
          "none"
        ],
        "required": true
      },
      "created_on": {
        "type": "date",
        "required": true
      }
    }
  },
  "contacts": {
    "notes": "Account contact records.",
    "writable": false,
    "selectors": [
      "contact_id",
      "account_id",
      "email"
    ],
