      "contact_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "name": {
        "type": "string",
        "required": true
      },
      "email": {
        "type": "string",
        "required": true
      },
      "role": {
        "type": "string",
        "enum": [
          "owner",
          "billing_admin",
          "developer"
        ],
        "required": true
      }
    }
  },
  "contracts": {
    "notes": "Signed account terms and service dates.",
    "writable": false,
    "selectors": [
      "contract_id",
      "account_id"
    ],
    "fields": {
      "contract_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "sla": {
        "type": "boolean",
        "required": true
      },
      "signed_terms": {
        "type": "string",
