      "start_on": {
        "type": "date",
        "required": true
      },
      "end_on": {
        "type": "date",
        "nullable": true,
        "required": true
      }
    }
  },
  "invoices": {
    "notes": "Invoice header records.",
    "writable": false,
    "selectors": [
      "invoice_id",
      "account_id"
    ],
