      "invoice_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "period_start": {
        "type": "date",
        "required": true
      },
      "period_end": {
        "type": "date",
        "required": true
      },
      "issued_on": {
        "type": "date",
        "required": true
      },
      "status": {
        "type": "string",
        "enum": [
          "open",
          "paid"
        ],
        "required": true
      },
      "total_cents": {
        "type": "integer",
        "required": true
      }
    }
  },
  "invoice_lines": {
    "notes": "Invoice line details and linked requests.",
    "writable": false,
    "selectors": [
      "line_id",
      "invoice_id"
    ],
    "fields": {
      "line_id": {
        "type": "string",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "required": true
      },
      "description": {
        "type": "string",
        "required": true
      },
      "product": {
        "type": "string",
        "enum": [
          "hosted_api",
          "embeddings",
          "batch",
          "dedicated",
          "plan_fee",
          "tax"
        ],
        "required": true
      },
      "period_start": {
        "type": "date",
        "required": true
      },
      "period_end": {
        "type": "date",
        "required": true
      },
      "amount_cents": {
        "type": "integer",
        "required": true
      },
      "request_ids": {
        "type": "string",
        "list": true,
        "ref": "usage",
        "required": true
      }
    }
  },
  "usage": {
    "notes": "Usage request records.",
    "writable": false,
    "selectors": [
      "request_id",
      "account_id",
      "line_id"
    ],
    "fields": {
      "request_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
