      "at": {
        "type": "utc",
        "required": true
      },
      "http_status": {
        "type": "integer",
        "required": true
      },
      "billed_tokens": {
        "type": "integer",
        "required": true
      },
      "cached_tokens": {
        "type": "integer",
        "required": true
      },
      "line_id": {
        "type": "string",
        "ref": "invoice_lines",
        "nullable": true,
        "required": true
      }
    }
