  "credit_grants": {
    "notes": "Granted account credits.",
    "writable": false,
    "selectors": [
      "grant_id",
      "account_id"
    ],
    "fields": {
      "grant_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
