        "type": "integer",
        "required": true
      },
      "remaining_cents": {
        "type": "integer",
        "required": true
      },
      "granted_on": {
        "type": "date",
        "required": true
      },
      "expires_on": {
        "type": "date",
        "nullable": true,
        "required": true
      }
    }
  },
  "credit_notes": {
    "notes": "Issued credit note records.",
    "writable": true,
    "selectors": [
      "credit_note_id",
      "account_id",
      "invoice_id"
    ],
    "fields": {
      "credit_note_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "required": true
      },
      "line_ids": {
        "type": "string",
        "list": true,
        "ref": "invoice_lines",
        "required": true
      },
      "amount_cents": {
        "type": "integer",
        "required": true
      },
      "reason": {
        "type": "string",
        "enum": [
          "duplicate",
          "service_credit",
          "goodwill"
        ],
        "required": true
      },
      "memo": {
        "type": "string",
        "default": "",
        "required": false
      },
      "status": {
        "type": "string",
        "enum": [
          "issued"
        ],
        "default": "issued",
        "required": false
      },
      "at": {
        "type": "integer",
        "required": false
      }
    }
  },
  "disputes": {
    "notes": "Billing dispute records.",
    "writable": true,
    "selectors": [
      "dispute_id",
      "account_id"
    ],
    "fields": {
      "dispute_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "nullable": true,
        "default": null,
        "required": false
      },
      "line_ids": {
        "type": "string",
        "list": true,
        "ref": "invoice_lines",
        "default": [],
        "required": false
      },
      "reason": {
        "type": "string",
        "enum": [
          "duplicate_charge",
          "incorrect_amount",
          "unrecognized_usage"
        ],
        "nullable": true,
        "default": null,
        "required": false
      },
      "request_ids": {
        "type": "string",
        "list": true,
        "ref": "usage",
        "default": [],
        "required": false
      },
      "window": {
        "type": "string",
        "default": "",
        "required": false
      },
      "status": {
        "type": "string",
        "enum": [
          "draft",
          "submitted"
        ],
        "required": true
      },
      "at": {
        "type": "integer",
        "required": false
      }
    }
  },
  "cases": {
    "notes": "Support case records.",
    "writable": true,
    "selectors": [
      "case_id",
      "account_id"
    ],
    "fields": {
      "case_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "team": {
        "type": "string",
        "enum": [
          "billing_ops",
          "billing_engineering",
          "finance",
          "legal",
          "account_team",
          "partnerships",
          "telemetry",
          "sre",
          "platform"
        ],
        "nullable": true,
        "default": null,
        "required": false
