      "summary": {
        "type": "string",
        "required": true
      },
      "details": {
        "type": "map<string,string>",
        "default": {},
        "required": false
      },
      "dispute_id": {
        "type": "string",
        "ref": "disputes",
        "nullable": true,
        "default": null,
        "required": false
      },
      "status": {
        "type": "string",
        "enum": [
          "draft",
          "escalated"
        ],
        "required": true
      },
      "at": {
        "type": "integer",
        "required": false
      }
    }
  }
