   "invoice_id": "PRACTICE-DUP-900",
   "line_ids": [
    "PRACTICE-DUP-900/L1",
    "PRACTICE-DUP-900/L2"
   ],
   "request_ids": [
    "req_practice_dup_900"
   ]
  },
  {
