   "account_id": "practice-emberquarry",
   "request_ids": [
    "req_practice_market_01"
   ]
  },
  {
   "id": "sla_contract",
   "description": "Enterprise account with a signed SLA contract.",
   "account_id": "practice-brackenvale",
   "contract_id": "PRACTICE-CONTRACT-SLA-01"
  }
 ]
}
{
  "version": 1,
  "cases": [
    {
      "id": "duplicate_180",
      "persona": "Startup engineer; short and direct.",
      "customer": {
        "opening": "Our August 2026 invoice has the same $180 hosted charge on it twice. Can you sort it out? Org alderwick-labs.",
        "agenda": [
          "What happens next?"
        ],
        "facts": {
          "org_id": "alderwick-labs",
          "invoice_id": "PRACTICE-DUP-180",
          "invoice_month": "August 2026",
          "line_items": "Two lines, both 'Repeated hosted request charge', $180 each.",
          "request_ids": "req_practice_dup_180"
        },
        "confirm": "yes"
      }
    },
    {
      "id": "duplicate_900",
      "persona": "Finance lead at an enterprise customer; formal.",
      "customer": {
        "opening": "We were billed $900 twice for dedicated capacity on our June 2026 invoice. Please refund one of them. Org copperfern-data.",
        "agenda": [
          "Thank you. Is that done now?"
        ],
        "facts": {
          "org_id": "copperfern-data",
          "invoice_id": "PRACTICE-DUP-900",
          "invoice_month": "June 2026",
          "line_items": "Two lines, both 'Repeated dedicated request charge', $900 each.",
          "plan": "Enterprise.",
          "contract": "We pay by invoice."
        },
        "confirm": "yes"
      }
    },
    {
      "id": "lookalike_180",
      "persona": "Ops manager; polite, a little worried.",
      "customer": {
        "opening": "Our May 2026 invoice shows two $180 hosted charges and it looks like we were charged twice. Can you check? Org dawnmere-cloud.",
        "agenda": [
          "So is it a duplicate or not?"
        ],
        "facts": {
          "org_id": "dawnmere-cloud",
          "invoice_id": "PRACTICE-LOOKALIKE",
          "invoice_month": "May 2026",
          "line_items": "Two lines, both 'Hosted inference request', $180 each.",
          "request_ids": "req_practice_look_1, req_practice_look_2"
        },
        "confirm": "yes"
      }
    },
    {
      "id": "marketplace_usage",
      "persona": "Platform engineer; brief.",
      "customer": {
        "opening": "We buy Redwood through AWS Marketplace. Where will request req_practice_market_01 from 12 September 2026 show up on our bill? Org emberquarry-systems.",
        "agenda": [
          "OK. Who do we talk to about that bill?"
        ],
        "facts": {
          "org_id": "emberquarry-systems",
          "request_ids": "req_practice_market_01",
          "response_status": "It returned 200."
        },
        "confirm": "yes"
      }
    },
    {
      "id": "sla_contract",
      "persona": "Enterprise account manager on the customer side; formal.",
      "customer": {
        "opening": "We had an outage on our side of the API last week. Does our contract entitle us to a service credit? Org brackenvale-ai.",
        "agenda": [
          "Who will follow up with us?"
        ],
        "facts": {
          "org_id": "brackenvale-ai",
          "contract": "We have a signed contract that includes an SLA.",
          "plan": "Growth.",
          "time_of_issue": "Most of one afternoon last week (UTC)."
        },
        "confirm": "yes"
      }
    }
  ]
}

