cd /tmp/work; python3 - <<'EOF'
from redwood_kit.billing import development_billing
import json
b=development_billing()
d=b.describe()
print(json.dumps({t:{k:v for k,v in d[t].items() if k!='fields'} for t in d},indent=0)[:3000])
print(json.dumps(d['credit_notes']['fields'],indent=0)[:1500])
print(json.dumps(d['cases']['fields'],indent=0)[:1500])
for acct in ['practice-ironbark','practice-juniper','practice-kestrel','practice-larchmont','practice-alderwick']:
    print('=====',acct)
    for t in ['accounts','contracts','invoices','usage','credit_grants','credit_ledger','credit_notes','disputes','cases']:
        try:
            r=b.query(t,{'account_id':acct})
        except Exception as e: print(t,'ERR',e); continue
        for row in r['rows']: print(t, json.dumps(row))
    for inv in b.query('invoices',{'account_id':acct})['rows']:
        for row in b.query('invoice_lines',{'invoice_id':inv['invoice_id']})['rows']: print('line',json.dumps(row))
EOF

